corrected_code:
def add_project_member(request, project_id):
    project = get_object_or_404(CloudProject, id=project_id, owner=request.user)
    new_user_id = request.POST.get('user_id')
    project.members.add(new_user_id)
    return JsonResponse({'status': 'member added'})

@receiver(m2m_changed, sender=CloudProject.members.through)
def on_member_added(sender, instance, action, pk_set, **kwargs):
    if action == 'post_add':
        for uid in pk_set:
            user = User.objects.get(id=uid)
            sts_token = aws_sts.generate_session_token(role_arn=instance.iam_role_arn)
            send_creds_email(user.email, sts_token)
